/** Aggregate observed facts only. No reference answers are generated by this report. */
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { config } from '../server/config.js';
import { Store } from '../server/store.js';
import { QualityStore } from '../server/quality.js';
import { PermissionStore } from '../server/data-permissions.js';

const store = new Store(config.dbPath), quality = new QualityStore(config.dbPath), permissions = new PermissionStore(config.dbPath);
try {
  const dashboard = quality.getDashboard(store);
  const manifest = quality.getManifest();
  const runs = manifest ? quality.listRuns(manifest.id) : [];
  const diagnostics = readdirSync('private/provider-attempts').filter(f => f.endsWith('.json')).map(file => JSON.parse(readFileSync(`private/provider-attempts/${file}`, 'utf8')));
  const failures = runs.filter(r => r.status === 'failed').map(run => {
    const diagnostic = diagnostics.find(d => d.model === run.model && typeof d.createdAt === 'string' && Math.abs(Date.parse(d.createdAt) + (d.latencyMs || 0) - Date.parse(run.createdAt)) < 1000);
    return { caseId: run.caseId, errorCode: run.errorCode, latencyMs: run.latencyMs, transport: diagnostic?.failure ?? null, validation: diagnostic?.validationFailure ?? null, reportedUsage: diagnostic?.usage ?? null };
  });
  const successLatencies = runs.filter(r => r.status === 'success').map(r => r.latencyMs).sort((a, b) => a - b);
  const middle = Math.floor(successLatencies.length / 2);
  const latency = { minMs: successLatencies[0] ?? null, medianMs: successLatencies.length ? successLatencies.length % 2 ? successLatencies[middle] : (successLatencies[middle - 1] + successLatencies[middle]) / 2 : null, maxMs: successLatencies.at(-1) ?? null };
  const firstRuns = manifest?.cases.flatMap(c => { const run = runs.find(r => r.caseId === c.id); return run ? [run] : []; }) ?? [];
  const evaluations = store.listEvaluations();
  const conversations = store.listConversations();
  const report = {
    capturedAt: new Date().toISOString(), model: config.model, mode: config.mode, modelChangedThisPhase: false, humanReferences: dashboard.referenceCount,
    validation: { manifestId: manifest?.id, cases: manifest?.cases.length ?? 0, metrics: dashboard.metrics, firstPass: { successful: firstRuns.filter(r => r.status === 'success').length, attempted: firstRuns.length }, successfulLatency: latency, failureDetails: failures },
    actualCounts: { conversations: conversations.length, devRecords: conversations.filter(c => c.groupId === 'DEV').length, liveEvaluations: evaluations.filter(e => e.status === 'live_validated').length, distinctAiConversations: new Set(evaluations.filter(e => e.status === 'live_validated').map(e => e.conversationVersion)).size, manualDemoEvaluations: evaluations.filter(e => e.status === 'manual_demo').length, actualHumanEnteredEvaluations: evaluations.filter(e => e.status === 'human_entered').length, mainAttemptLedger: store.listEvaluationAttempts().length, explicitDataPermissions: conversations.filter(c => permissions.getPermission(c.version)).length },
    limitations: ['Agreement/MAE/N/A and gross FP/FN remain unavailable until actual human references exist.', 'Technical quote validity does not prove semantic correctness.', 'Voice manual_demo records are acceptance fixtures, not operator-quality verdicts.', 'Official control group and exact code-freeze time not supplied.'],
  };
  mkdirSync('private/reports', { recursive: true }); writeFileSync('private/reports/next-phase-report.json', JSON.stringify(report, null, 2));
  console.log(JSON.stringify({ model: report.model, humanReferences: report.humanReferences, actualCounts: report.actualCounts, firstPass: report.validation.firstPass, successfulLatency: latency, reliability: dashboard.metrics?.reliability, technicalEvidence: dashboard.metrics?.evidence, failures }, null, 2));
} finally { permissions.close(); quality.close(); store.close(); }
